            return false;
        }

        if (ExileController.Instance.AsBoolFast() || Minigame.Instance.AsBoolFast()) return false;

        var localPlayer = AmongUsLLImpl.LocalPlayer;
        if (!localPlayer.CanMove && !MeetingHud.Instance.AsBoolFast()) {
