            return false;
        }

        __instance.SabText.gameObject.SetActive(true);
        __instance.SabText.text = Language.Translate("console.notAvailable");

        foreach (var panel in __instance.vitals) panel.gameObject.SetActive(false);

        return false;
    }
}

