[HarmonyPatch(typeof(KillButton), nameof(KillButton.DoClick))]
public static class KillButtonClickPatch
{
    static bool Prefix(KillButton __instance)
    {
        if (__instance.enabled && NebulaGameManager.Instance?.KillButtonTracker?.CurrentTarget != null 
            && !__instance.isCoolingDown && __instance.graphic.color.a > 0.9f 
            && !AmongUsLLImpl.LocalPlayer.Data.IsDead && AmongUsLLImpl.LocalPlayer.CanMove)
        {
            var target = NebulaGameManager.Instance?.KillButtonTracker?.CurrentTarget!;
            var cancelable = GameOperatorManager.Instance?.Run(new PlayerTryVanillaKillLocalEventAbstractPlayerEvent(GamePlayer.LocalPlayer!, target));
            if (!(cancelable?.IsCanceled ?? false))
            {
                GamePlayer.LocalPlayer?.MurderPlayer(target, PlayerState.Dead, EventDetail.Kill, Virial.Game.KillParameter.NormalKill);
            }
            if (cancelable?.ResetCooldown ?? false) NebulaAPI.CurrentGame?.KillButtonLikeHandler.StartCooldown();
            __instance.SetTarget(null);
        }
        return false;
    }
}

